// dex number / Chinese name / English name all work
const BY_NAME = {};
for (const k of Object.keys(BUDDIES)) {
  const b = BUDDIES[k];
  BY_NAME[b.name.toLowerCase()] = b.dex;
  if (b.en) BY_NAME[b.en.toLowerCase()] = b.dex;
}

export function findBuddy(id) {
  if (id == null) return null;
  const key = String(id).trim().toLowerCase();
  if (BUDDIES[key]) return BUDDIES[key];
  const dex = BY_NAME[key];
  return dex ? BUDDIES[String(dex)] : null;
}
